import java.io.*; import java.util.*; class Result { public static int shortPalindrome(String s) { long MOD = 1000000007; long[] c1 = new long[26]; long[][] c2 = new long[26][26]; long[] c3 = new long[26]; long count4 = 0; for (int i = 0; i < s.length(); i++) { int charIdx = s.charAt(i) - 'a'; count4 = (count4 + c3[charIdx]) % MOD; for (int j = 0; j < 26; j++) { c3[j] = (c3[j] + c2[j][charIdx]) % MOD; } for (int j = 0; j < 26; j++) { c2[j][charIdx] = (c2[j][charIdx] + c1[j]) % MOD; } c1[charIdx]++; } return (int) count4; } } public class Solution { public static void main(String[] args) throws IOException { BufferedReader bufferedReader = new BufferedReader(new InputStreamReader(System.in)); BufferedWriter bufferedWriter = new BufferedWriter(new FileWriter(System.getenv("OUTPUT_PATH"))); String s = bufferedReader.readLine(); int result = Result.shortPalindrome(s); bufferedWriter.write(String.valueOf(result)); bufferedWriter.newLine(); bufferedReader.close(); bufferedWriter.close(); } }